"""Build the shareable comparison from recorded experiment results."""
import json
from multicrop_bench import OUT
from model import read


def main():
    data=read(OUT/'report.json');adaptive=read(OUT/'adaptive/report.json')
    payload=json.dumps(dict(runs=data['runs'],adaptive=adaptive),ensure_ascii=False).replace('<','\\u003c')
    html='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><style>
body{margin:0;color:var(--foreground,CanvasText);font-family:var(--font-sans,Arial,sans-serif);font-size:14px;line-height:1.5}p{margin:12px 0}h2{font-size:17px;line-height:1.3;margin:22px 0 12px}small,.note{font-size:13px;color:var(--muted-foreground,GrayText)}button,select{font:inherit;color:var(--foreground,CanvasText);background:var(--secondary,Canvas);border:1px solid var(--border,GrayText);padding:6px 9px;border-radius:var(--radius,4px)}select:focus-visible{outline:2px solid var(--ring,Highlight);outline-offset:2px}.controls{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:0 0 12px}.legend{display:flex;gap:16px;flex-wrap:wrap;margin-bottom:8px}.legend span{display:inline-flex;gap:6px;align-items:center}.dot{width:10px;height:10px;border-radius:50%}.chart{height:280px;width:100%;display:block}table{border-collapse:collapse;width:100%;font-size:13px}th,td{text-align:right;padding:8px 7px;border-bottom:1px solid var(--border,GrayText);font-variant-numeric:tabular-nums}th:first-child,td:first-child{text-align:left}caption{text-align:left;font-weight:600;margin:14px 0 5px}.flow{display:flex;flex-wrap:wrap;gap:10px 24px;align-items:baseline;margin:14px 0}.flow strong{font-size:17px}.c0{background:var(--chart-1,Highlight)}.c1{background:var(--chart-2,Highlight)}.c2{background:var(--chart-3,Highlight)}.c3{background:var(--chart-4,Highlight)}summary{cursor:pointer;text-decoration:underline;text-underline-offset:3px}@media(max-width:450px){th,td{padding:7px 3px;font-size:12px}.legend{gap:6px 12px}.chart{height:240px}}
</style></head><body>
<div class="controls"><label for="metric">Compare</label><select id="metric"><option value="agreement">Label agreement</option><option value="high">Agreement among high-confidence clean matches</option><option value="coverage">High-confidence clean coverage</option></select></div>
<div class="legend" aria-label="Models"><span><i class="dot c0"></i>Terra</span><span><i class="dot c1"></i>Sol</span><span><i class="dot c2"></i>Luna</span><span><i class="dot c3"></i>Jev 1.14</span></div>
<svg id="chart" class="chart" viewBox="0 0 700 280" role="img" aria-label="Model comparison across 32, 64 and 128 crops per grid"></svg>
<table id="counts"><caption>Same 128 crops at each grid size</caption><thead><tr><th>Model</th><th>32 crops</th><th>64 crops</th><th>128 crops</th></tr></thead><tbody></tbody></table>
<p class="note">Exact agreement with saved human labels, not verified accuracy. This selected development sample contains one previously confirmed CLAYSTONE/LIMESTONE reference error; its label was kept unchanged.</p>
<table id="times"><caption>Observed labeling workflow seconds</caption><thead><tr><th>Model</th><th>32 crops</th><th>64 crops</th><th>128 crops</th></tr></thead><tbody></tbody></table>
<p class="note">One run per setting, with concurrent work. Native agent time runs from its first tool to validation. Jev time covers direct API requests and data handling. These timings do not compare raw model latency. Terra-32 lost its timer. Luna-64 includes matrix and source-ID repair.</p>
<h2>Cluster first, then inspect hard groups</h2><div class="flow"><span><strong>128</strong> crops</span><span>→ <strong>51</strong> pixel groups</span><span>→ <strong>71</strong> larger-detail queries</span></div>
<p>Clustering and representative grids took 0.68 seconds. The Jev screen matched 115/128 saved labels. Larger views with up to two unlabelled neighbours rescued six labels, reaching 121/128. The sum of measured stages was about 84.8 seconds.</p>
<p>The adaptive pass did not beat flat Sol at 125/128 in 74.2 seconds. Clusters remain useful for sorting and caching. Copying a representative label to every member still needs a check.</p>
<details><summary>Limits and retained evidence</summary><p>Four models used the same native crop pixels and source legends. Separate native sessions tested each grid size. Only one primary ID is scored; mixed-fill flags have no complete boundary ground truth. Native token use was not captured. Jev image inputs used its image header and returned model jev-1.14.0. All matrices, source hashes, API usage, route reasons and disagreements are retained. No live annotations changed.</p></details>
<script>const DATA=__DATA__;const names=['terra','sol','luna','jev'],labels=['Terra','Sol','Luna','Jev 1.14'],sizes=[32,64,128],ns='http://www.w3.org/2000/svg';
function node(tag,attrs,text){const e=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text!==undefined)e.textContent=text;return e;}
function run(n,s){return DATA.runs.find(r=>r.run===n+'-'+s)}function value(r,m){return m==='high'?100*r.high_clean_matched/r.high_clean:m==='coverage'?100*r.high_clean/128:100*r.matched/128}
function draw(){const svg=document.getElementById('chart'),metric=document.getElementById('metric').value,W=innerWidth<450?390:700,start=W<450?54:88,gap=(W-2*start)/2;svg.setAttribute('viewBox','0 0 '+W+' 280');svg.replaceChildren();for(let pct=0;pct<=100;pct+=20){const y=235-pct*2;svg.append(node('line',{x1:52,y1:y,x2:W-24,y2:y,stroke:'var(--border,GrayText)'}),node('text',{x:42,y:y+4,'text-anchor':'end',fill:'var(--muted-foreground,GrayText)','font-size':12},pct+'%'));}
sizes.forEach((s,i)=>svg.append(node('text',{x:start+i*gap,y:264,'text-anchor':'middle',fill:'var(--foreground,CanvasText)','font-size':13},s+' crops')));
names.forEach((name,i)=>{const points=sizes.map((s,j)=>({r:run(name,s),x:start+j*gap})).filter(v=>v.r).map(v=>({...v,y:235-2*value(v.r,metric)}));const color='var(--chart-'+(i+1)+',Highlight)';svg.append(node('polyline',{points:points.map(v=>v.x+','+v.y).join(' '),fill:'none',stroke:color,'stroke-width':2.5}));points.forEach(v=>{const c=node('circle',{cx:v.x,cy:v.y,r:4.5,fill:color,tabindex:0});c.append(node('title',{},labels[i]+', '+v.r.size+' crops: '+value(v.r,metric).toFixed(1)+'%; '+v.r.matched+'/128 labels; '+(v.r.seconds===null?'time not measured':v.r.seconds.toFixed(1)+' seconds')));svg.append(c);});});}
for(const [table,metric]of [['counts','matched'],['times','seconds']]){const body=document.querySelector('#'+table+' tbody');names.forEach((name,i)=>{const row=document.createElement('tr'),label=document.createElement('th');label.scope='row';label.textContent=labels[i];row.append(label);sizes.forEach(size=>{const r=run(name,size),td=document.createElement('td');td.textContent=metric==='matched'?r.matched+'/128':r.seconds===null?'not measured':r.seconds.toFixed(1)+(r.first_pass_issue?'*':'');row.append(td);});body.append(row);});}
document.getElementById('metric').onchange=draw;addEventListener('resize',draw);draw();</script></body></html>'''.replace('__DATA__',payload)
    (OUT/'comparison.html').write_text(html,encoding='utf-8');print('Comparison HTML written.')


if __name__=='__main__':main()
